// NewRecordDecisionPayload builds a mcpApproval service recordDecision
// endpoint payload.
func NewRecordDecisionPayload(body *RecordDecisionRequestBody, sessionToken *string, apikeyToken *string, projectSlugInput *string) *mcpapproval.RecordDecisionPayload {
	v := &mcpapproval.RecordDecisionPayload{
		ID:               *body.ID,
		Decision:         *body.Decision,
		Rationale:        *body.Rationale,
		ResearchReportID: body.ResearchReportID,
	}
	if body.GrantedPrincipalUrns != nil {
		v.GrantedPrincipalUrns = make([]string, len(body.GrantedPrincipalUrns))
		for i, val := range body.GrantedPrincipalUrns {
			v.GrantedPrincipalUrns[i] = val
		}
	}
	v.SessionToken = sessionToken
	v.ApikeyToken = apikeyToken
	v.ProjectSlugInput = projectSlugInput

	return v
}

// ValidateRecordDecisionRequestBody runs the validations defined on
// RecordDecisionRequestBody
func ValidateRecordDecisionRequestBody(body *RecordDecisionRequestBody) (err error) {
	if body.ID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("id", "body"))
	}
	if body.Decision == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("decision", "body"))
	}
	if body.Rationale == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("rationale", "body"))
	}
	if body.Decision != nil {
		if !(*body.Decision == "approved" || *body.Decision == "denied") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.decision", *body.Decision, []any{"approved", "denied"}))
		}
	}
	return
}
